'use client';
import {InternalChat,requestRecordChat} from '@/components/internal-chat';
import type {SupabaseClient} from '@supabase/supabase-js';
const conversations=['Mecânico A','Mecânico B'].map((name,i)=>({id:`chat-${i}`,title:'PR-CHT · Pane',participants:`Teste, ${name}`,members:[{id:'test',name:'Teste'},{id:`m${i}`,name}],record_id:'rec',post_id:null,message_count:i+1,unread:0,updated_at:new Date().toISOString()}));
const client={rpc:async(name:string,args:{p_action:string;p_record_id?:string})=>({error:null,data:name==='maintenance_chat'?{record:{id:args.p_record_id,prefix:'PR-CHT',title:'Pane',type:'fault'},exists:args.p_record_id!=='empty',member:args.p_record_id!=='empty',conversations:args.p_record_id==='empty'?[]:conversations,links:[]}:name==='internal_chat'?(args.p_action==='list'?conversations:args.p_action==='people'?[{id:'m0',name:'Mecânico A'}]:{}):[]}),channel:()=>{const c={on:()=>c,subscribe:()=>c};return c;},removeChannel:async()=>{}} as unknown as SupabaseClient;
export default function Page(){return <div><button onClick={()=>requestRecordChat('rec')}>Abrir minhas conversas</button><button onClick={()=>requestRecordChat('empty')}>Sem conversa</button><InternalChat aircraft={[]} supabase={client} user="test" directory={{}} onOpenActivity={()=>{}} requireSignature={async()=>true} onEnablePush={async()=>{}} renderAssistant={()=>null}/></div>}
